script:
const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

// ---- Profile ----

async function openEditProfileModal() {
  const userName = page_data.user.user;
  if (!userName || userName === "Guest") {
    toast.error("You must be logged in to edit your profile");
    return;
  }

  const u = page_data.user;
  const currentHandle = u.handle
    ? u.handle.includes("@")
      ? u.handle.split("@")[1]
      : u.handle
    : "";

  renderFormDialog({
    title: "Edit Profile",
    size: "md",
    saveLabel: "Save Changes",
    fields: [
      {
        type: "text",
        id: "edit-first-name",
        label: "First Name",
        value: u.first_name || "",
      },
      {
        type: "text",
        id: "edit-last-name",
        label: "Last Name",
        value: u.last_name || "",
      },
      {
        type: "text",
        id: "edit-handle",
        label: "Handle",
        value: currentHandle,
      },
      {
        type: "text",
        id: "edit-company",
        label: "Company",
        value: u.company || "",
      },
      {
        type: "text",
        id: "edit-designation",
        label: "Designation",
        value: u.designation || "",
      },
      {
        type: "textarea",
        id: "edit-bio",
        label: "Bio",
        value: u.bio || "",
        rows: 3,
      },
    ],
    onSave: async (values, close) => {
      try {
        if (
          values["edit-first-name"] !== u.first_name ||
          values["edit-last-name"] !== u.last_name
        ) {
          await frappeClient.setValue("User", userName, {
            first_name: values["edit-first-name"],
            last_name: values["edit-last-name"],
          });
        }

        const updates = {};
        if (values["edit-handle"] !== currentHandle)
          updates.handle = values["edit-handle"];
        if (values["edit-company"] !== u.company)
          updates.company = values["edit-company"];
        if (values["edit-designation"] !== u.designation)
          updates.designation = values["edit-designation"];
        if (values["edit-bio"] !== u.bio) updates.bio = values["edit-bio"];

        if (Object.keys(updates).length > 0) {
          await frappeClient.setValue("Cafe User", userName, updates);
        }

        toast.success("Profile updated successfully");
        close();

        if (updates.handle) {
          const url = new URL(location.href);
          url.pathname = url.pathname.replace(currentHandle, updates.handle);
          location.href = url.href;
        } else {
          window.scrollPositionManager?.save(
            document.getElementById("main-body"),
          );
          location.reload();
        }
      } catch (error) {
        console.error(error);
        toast.error(error.message || "Failed to update profile");
      }
    },
  });
}

// ---- Introduction ----

async function openEditIntroModal() {
  const userName = page_data.user.user;
  if (!userName || userName === "Guest") {
    toast.error("You must be logged in to edit your intro");
    return;
  }

  const currentIntro =
    document.getElementById("intro-content")?.innerText || "";

  renderFormDialog({
    title: "Edit Introduction",
    size: "md",
    saveLabel: "Save Changes",
    fields: [
      {
        type: "textarea",
        id: "edit-intro-content",
        label: "Introduction",
        value: currentIntro,
        rows: 8,
      },
    ],
    onSave: async (values, close) => {
      try {
        await frappeClient.setValue("Cafe User", userName, {
          introduction: values["edit-intro-content"],
        });
        toast.success("Introduction updated");
        window.scrollPositionManager?.save(
          document.getElementById("main-body"),
        );
        close();
        location.reload();
      } catch (error) {
        console.error(error);
        toast.error(error.message || "Failed to update introduction");
      }
    },
  });
}

// ---- Experience (Work / Education) shared helpers ----

function buildExperienceFields({
  titleLabel,
  orgLabel,
  currentlyLabel,
  includeDescription = true,
  item = {},
}) {
  const isCurrent = !!item.is_current;
  return [
    {
      type: "text",
      id: "exp-title",
      label: titleLabel,
      value: item.title || "",
      required: true,
    },
    {
      type: "text",
      id: "exp-org",
      label: orgLabel,
      value: item.organization || "",
      required: true,
    },
    {
      type: "row",
      fields: [
        {
          type: "select",
          id: "exp-from-month",
          label: "From Month",
          value: item.from_month || "",
          options: MONTHS,
          flex: 1,
        },
        {
          type: "number",
          id: "exp-from-year",
          label: "From Year",
          value: item.from_year || "",
          placeholder: "YYYY",
          required: true,
          flex: 1,
        },
      ],
    },
    {
      type: "checkbox",
      id: "exp-is-current",
      label: `I currently ${currentlyLabel} here`,
      value: isCurrent,
      toggles: "exp-to-date-row",
    },
    {
      type: "row",
      id: "exp-to-date-row",
      hidden: isCurrent,
      fields: [
        {
          type: "select",
          id: "exp-to-month",
          label: "To Month",
          value: item.to_month || "",
          options: MONTHS,
          flex: 1,
        },
        {
          type: "number",
          id: "exp-to-year",
          label: "To Year",
          value: item.to_year || "",
          placeholder: "YYYY",
          flex: 1,
        },
      ],
    },
    ...(includeDescription
      ? [
          {
            type: "textarea",
            id: "exp-description",
            label: "Description",
            value: item.description || "",
            rows: 3,
          },
        ]
      : []),
  ];
}

function validateExperienceValues(values) {
  if (!values["exp-title"] || !values["exp-org"] || !values["exp-from-year"]) {
    toast.error("Please fill all required fields");
    return false;
  }
  if (!values["exp-is-current"]) {
    if (!values["exp-to-month"] && values["exp-from-month"]) {
      toast.error("Please provide To Month");
      return false;
    }
    if (!values["exp-to-year"]) {
      toast.error("Please provide To Year");
      return false;
    }
  }
  return true;
}

function buildExperiencePayload(values, extra = {}) {
  const isCurrent = values["exp-is-current"] ? 1 : 0;
  return {
    title: values["exp-title"],
    organization: values["exp-org"],
    from_month: values["exp-from-month"],
    from_year: parseInt(values["exp-from-year"], 10),
    is_current: isCurrent,
    description: values["exp-description"],
    to_month: isCurrent ? "" : values["exp-to-month"],
    to_year: isCurrent
      ? null
      : values["exp-to-year"]
        ? parseInt(values["exp-to-year"], 10)
        : null,
    ...extra,
  };
}

// ---- Add Experience ----

async function openAddExperienceModal(type) {
  const userName = page_data.user.user;
  if (!userName || userName === "Guest") {
    toast.error("You must be logged in to add experience");
    return;
  }

  const isWork = type === "Work";

  renderFormDialog({
    title: `Add ${isWork ? "Work History" : "Education"}`,
    size: "md",
    saveLabel: "Save",
    fields: buildExperienceFields({
      titleLabel: isWork ? "Job Title" : "Degree",
      orgLabel: isWork ? "Company" : "School/University",
      currentlyLabel: isWork ? "work" : "study",
      includeDescription: isWork,
    }),
    onSave: async (values, close) => {
      if (!validateExperienceValues(values)) return;

      const payload = buildExperiencePayload(values, {
        parent: userName,
        parenttype: "Cafe User",
        parentfield: isWork ? "work_history" : "education",
        experience_type: type,
      });

      try {
        await frappeClient.post("Cafe User Experience", payload);
        toast.success(`${type} added successfully`);
        window.scrollPositionManager?.save(
          document.getElementById("main-body"),
        );
        close();
        location.reload();
      } catch (error) {
        console.error(error);
        toast.error(error.message || "Failed to add experience");
      }
    },
  });
}

// ---- Edit Experience (Work & Education) ----

async function openEditExperienceItemModal(id, type) {
  const userName = page_data.user.user;
  if (!userName || userName === "Guest") {
    toast.error("You must be logged in to edit this");
    return;
  }

  const isWork = type === "Work";
  let item;
  try {
    const response = await frappeClient.getDoc("Cafe User Experience", id);
    item = response?.data || response;
  } catch {
    toast.error(`Could not load ${isWork ? "work history" : "education"} item`);
    return;
  }

  renderFormDialog({
    title: `Edit ${isWork ? "Work History" : "Education"}`,
    size: "md",
    saveLabel: "Save Changes",
    fields: buildExperienceFields({
      titleLabel: isWork ? "Job Title" : "Degree",
      orgLabel: isWork ? "Company" : "School/University",
      currentlyLabel: isWork ? "work" : "study",
      includeDescription: isWork,
      item,
    }),
    onSave: async (values, close) => {
      if (!validateExperienceValues(values)) return;

      try {
        await frappeClient.update(
          "Cafe User Experience",
          id,
          buildExperiencePayload(values),
        );
        toast.success(
          `${isWork ? "Work history" : "Education"} updated successfully`,
        );
        window.scrollPositionManager?.save(
          document.getElementById("main-body"),
        );
        close();
        location.reload();
      } catch (error) {
        console.error(error);
        toast.error(
          error.message ||
            `Failed to update ${isWork ? "work history" : "education"}`,
        );
      }
    },
  });
}

// ---- Delete Experience ----

function deleteExperienceItem(id, type) {
  const userName = page_data.user.user;
  if (!userName || userName === "Guest") {
    toast.error(
      `You must be logged in to delete ${type === "Work" ? "work history" : "education"}`,
    );
    return;
  }

  const isWork = type === "Work";
  const label = isWork ? "Work History" : "Education";

  dialog({
    title: `Delete ${label}`,
    message: `Are you sure you want to delete this ${label.toLowerCase()} entry? This cannot be undone.`,
    size: "sm",
    actions: [
      {
        label: "Delete",
        variant: "solid",
        theme: "red",
        onClick: async (close) => {
          try {
            await frappeClient.delete("Cafe User Experience", id);
            toast.success(`${label} deleted`);
            window.scrollPositionManager?.save(
              document.getElementById("main-body"),
            );
            close();
            location.reload();
          } catch (error) {
            console.error(error);
            toast.error(
              error.message || `Failed to delete ${label.toLowerCase()}`,
            );
          }
        },
      },
      { label: "Cancel", onClick: (close) => close() },
    ],
  });
}

// ---- Init ----

function init() {
  const introContent = document.getElementById("intro-content");
  const showMoreBtn = document.getElementById("show-more-intro");
  if (introContent && showMoreBtn) {
    const computedStyle = getComputedStyle(introContent);
    const lineHeightVal = computedStyle.lineHeight;
    const lineHeight =
      lineHeightVal === "normal"
        ? parseFloat(computedStyle.fontSize) * 1.2
        : parseFloat(lineHeightVal);
    const lineCount = Math.round(introContent.scrollHeight / lineHeight);
    if (introContent.scrollHeight <= 560 && lineCount <= 3) {
      showMoreBtn.style.display = "none";
    }
  }

  document
    .getElementById("edit-profile-button")
    ?.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openEditProfileModal();
    });

  document.getElementById("edit-intro")?.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    openEditIntroModal();
  });

  document
    .getElementById("add-work-history")
    ?.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openAddExperienceModal("Work");
    });

  document
    .getElementById("add-education-history")
    ?.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openAddExperienceModal("Education");
    });

  document.querySelectorAll(".edit-work-item").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const id = btn.getAttribute("work-history-id");
      if (id) openEditExperienceItemModal(id, "Work");
    });
  });

  document.querySelectorAll(".delete-work-btn").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const id = btn.getAttribute("work-history-id");
      if (id) deleteExperienceItem(id, "Work");
    });
  });

  document.querySelectorAll(".edit-education-item").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const id = btn.getAttribute("education-history-id");
      if (id) openEditExperienceItemModal(id, "Education");
    });
  });

  document.querySelectorAll(".delete-education-btn").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const id = btn.getAttribute("education-history-id");
      if (id) deleteExperienceItem(id, "Education");
    });
  });
}

init();
